<template>
  <section class="dashboard">
    <header class="dash-head"><div><p class="eyebrow">PANEL ADMIN</p><h1>Kelola website</h1><p class="muted">Perbarui informasi utama dan pantau pesan pengunjung.</p></div><button class="secondary" @click="logout">Keluar</button></header>
    <p v-if="notice" class="notice">{{ notice }}</p>
    <div class="grid">
      <article class="panel content-panel"><div class="panel-title"><h2>Konten halaman utama</h2><button @click="saveContent">Simpan perubahan</button></div><label>Judul<textarea v-model="content.title" rows="2"></textarea></label><label>Deskripsi<textarea v-model="content.content" rows="5"></textarea></label></article>
      <article class="panel"><div class="panel-title"><h2>Pesan masuk</h2><span class="count">{{ inquiries.length }}</span></div><div v-if="!inquiries.length" class="empty">Belum ada pesan.</div><div v-for="item in inquiries" :key="item.id" class="inquiry"><div><strong>{{ item.name }}</strong><span>{{ item.email }}</span></div><p>{{ item.message }}</p><select v-model="item.status" @change="updateStatus(item)"><option value="new">Baru</option><option value="read">Dibaca</option><option value="replied">Dibalas</option><option value="archived">Arsip</option></select></div></article>
    </div>
  </section>
</template>
<script>
import { supabase } from "../lib/supabase";
export default { name: "AdminDashboard", data: () => ({ content: { title: "", content: "" }, inquiries: [], notice: "" }), async mounted() { if (!supabase) return; const { data: { user } } = await supabase.auth.getUser(); if (!user) return this.$router.replace("/admin/login"); const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).single(); if (!profile || profile.role !== "admin") return this.$router.replace("/"); await this.load(); }, methods: { async load() { const [{ data: content }, { data: inquiries }] = await Promise.all([supabase.from("site_content").select("title,content").eq("slug", "home").single(), supabase.from("inquiries").select("id,name,email,message,status,created_at").order("created_at", { ascending: false })]); if (content) this.content = content; this.inquiries = inquiries || []; }, async saveContent() { const { error } = await supabase.from("site_content").update({ title: this.content.title, content: this.content.content, updated_at: new Date().toISOString() }).eq("slug", "home"); this.notice = error ? "Gagal menyimpan perubahan." : "Konten berhasil diperbarui."; }, async updateStatus(item) { await supabase.from("inquiries").update({ status: item.status }).eq("id", item.id); }, async logout() { await supabase.auth.signOut(); this.$router.replace("/admin/login"); } } };
</script>
<style scoped>
.dashboard{padding:48px max(20px,calc((100% - 1120px)/2));background:#f7f4ee;min-height:70vh}.dash-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:28px}.eyebrow{color:#b48138;font-weight:800;letter-spacing:.14em;font-size:12px}.muted{color:#66736d}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:22px}.panel{background:#fff;border-radius:18px;padding:24px;box-shadow:0 12px 35px #233b3510}.panel-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:22px}.panel h2{margin:0;color:#233b35;font-size:20px}.content-panel label{display:grid;gap:8px;margin-top:18px;font-weight:700;color:#233b35}.content-panel textarea{font:inherit;border:1px solid #d9ded8;border-radius:10px;padding:12px;resize:vertical}.panel button{background:#b48138;color:#fff;border:0;border-radius:9px;padding:10px 14px;font-weight:700}.secondary{background:transparent!important;color:#233b35!important;border:1px solid #c9d0c8!important}.count{background:#edf0e8;border-radius:30px;padding:5px 10px}.inquiry{border-top:1px solid #edf0e8;padding:16px 0}.inquiry div{display:flex;justify-content:space-between;gap:10px}.inquiry span,.inquiry p{color:#66736d;font-size:14px}.inquiry select{border:1px solid #d9ded8;border-radius:8px;padding:7px}.notice{background:#e6f2e9;padding:12px;border-radius:10px;color:#23613c}.empty{color:#66736d}@media(max-width:760px){.grid{grid-template-columns:1fr}.dash-head{flex-direction:column}.inquiry div{display:grid}}
</style>
